using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using System.Drawing;using System.Windows.Forms;using System.Reflection;using CircuitoStudio;
internal static class SwitchgearSelectionTests {
static int n;static void Check(bool ok,string label){n++;if(!ok)throw new Exception(label);}static void Reject(Action a,string label){bool rejected=false;try{a();}catch(InvalidDataException){rejected=true;}Check(rejected,label);}
static Project Fixture(){var p=new Project();p.Source.LineVoltage=400;p.Source.ShortCircuitKA=6;var b=new Board{Id="Q",Voltage=400};var c=new Circuit{Id="C",Phases=PhaseMode.Trifasico,PhaseLabel="ABC",Voltage=400,PowerKw=8*Math.Sqrt(3),PowerFactor=1,CableMm2=10,LengthM=10};c.Cable.AmpacityA=32;b.Circuits.Add(c);p.Boards.Add(b);BreakerSelection.Apply(p,c,new BreakerRating{Manufacturer="QA",Reference="BR25",VoltageV=400,FrequencyHz=60,Poles=PoleLayout.ThreePole,Metric=BreakingMetric.Icu,RatedA=25,CapacityKA=10,I2A=36.25,Source="Fonte QA",DataVersion="2026.10",Standard="QA",Sheet="QA"},PoleLayout.ThreePole,BreakingMetric.Icu);c.Protection.DisconnectSeconds=.1;return p;}
static SwitchgearRating Fuse(){return new SwitchgearRating{Manufacturer="QA sintético",Reference="GG25",Family=SwitchgearFamily.gG,VoltageV=400,FrequencyHz=60,Poles=PoleLayout.ThreePole,RatedA=25,BreakingKA=50,I2A=40,Source="Ensaio; \"A\" Ω",DataVersion="2026.10",Standard="Classe declarada QA",Sheet="Dados sintéticos sem certificação"};}
static SwitchgearRating Switch(){var r=Fuse();r.Reference="SW40";r.Family=SwitchgearFamily.AC23A;r.RatedA=40;r.BreakingKA=r.I2A=0;r.IcwKA=10;r.IcwSeconds=1;r.IcmPeakKA=25;return r;}
static SwitchgearEvaluation Eval(Project p,SwitchgearRating r){var c=p.Boards[0].Circuits[0];return SwitchgearSelection.Evaluate(p,Engineering.Analyze(p),c,SwitchgearSelection.Candidate(c,r,r.Family,PoleLayout.ThreePole,true));}
[STAThread]public static int Main(){string dir=Path.Combine(Path.GetTempPath(),"switchgear-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{var p=Fixture();var c=p.Boards[0].Circuits[0];var r=Fuse();Check(Eval(p,r).Status=="Atende comparações nominais","full range fuse matches Ib Iz I2 and interruption");r.RatedA=19;Check(Eval(p,r).Status=="Não atende","fuse In below Ib rejected");r=Fuse();r.RatedA=33;Check(Eval(p,r).Status=="Não atende","full range fuse above Iz rejected");r=Fuse();r.I2A=47;Check(Eval(p,r).Status=="Não atende","fuse I2 above 1.45 Iz rejected");r=Fuse();r.BreakingKA=5;Check(Eval(p,r).Status=="Não atende","fuse insufficient interruption rejected");r=Fuse();r.I2A=0;Check(Eval(p,r).Status=="Dados incompletos","unknown I2 not guessed from family");r=Fuse();r.Family=SwitchgearFamily.aM;Check(Eval(p,r).Status=="Dados incompletos"&&Eval(p,r).Detail.Contains("faixa parcial"),"aM cannot be approved as overload protection");r=Fuse();r.VoltageV=415;Check(Eval(p,r).Status=="Não atende","higher voltage condition not extrapolated");r=Fuse();r.FrequencyHz=50;Check(Eval(p,r).Status=="Não atende","frequency mismatch rejected");r=Fuse();r.Poles=PoleLayout.FourPole;Check(Eval(p,r).Status=="Não atende","wrong required poles rejected");r=Fuse();var other=SwitchgearSelection.Candidate(c,r,SwitchgearFamily.aM,PoleLayout.ThreePole,true);Check(SwitchgearSelection.Evaluate(p,Engineering.Analyze(p),c,other).Status=="Não atende","required family must match exactly");
r=Switch();Check(Eval(p,r).Status=="Atende comparações nominais","switch rated current withstand duration and making peak compared");Check(r.RatedA>c.Cable.AmpacityA&&Eval(p,r).Status=="Atende comparações nominais","switch is not misused as overload protection requiring In below Iz");r.Family=SwitchgearFamily.AC20A;Check(Eval(p,r).Status=="Não atende","AC20 cannot perform required load switching");other=SwitchgearSelection.Candidate(c,r,r.Family,PoleLayout.ThreePole,false);Check(SwitchgearSelection.Evaluate(p,Engineering.Analyze(p),c,other).Status=="Atende comparações nominais","AC20 may be selected for no-load isolation only");r=Switch();r.IcwKA=5;Check(Eval(p,r).Status=="Não atende","insufficient short time withstand rejected");r=Switch();r.IcwSeconds=.05;Check(Eval(p,r).Status=="Não atende","clearing time beyond rated withstand rejected");r=Switch();r.IcmPeakKA=10;Check(Eval(p,r).Status=="Não atende","insufficient making peak rejected");r=Switch();c.Protection.DisconnectSeconds=0;Check(Eval(p,r).Status=="Dados incompletos","unknown clearing time remains pending");c.Protection.DisconnectSeconds=.1;p.Source.ShortCircuitKA=0;Check(Eval(p,r).Status=="Dados incompletos","unknown fault current not treated as a failure or approval");p.Source.ShortCircuitKA=6;var primary=c.Protection.BreakerSnapshot;c.Protection.BreakerSnapshot=null;Check(Eval(p,r).Status=="Dados incompletos","switch without identified protecting device remains pending");c.Protection.BreakerSnapshot=primary;
SwitchgearSelection.Apply(p,c,r,r.Family,PoleLayout.ThreePole,true);Check(c.BreakerA==25&&c.Protection.BreakingCapacityKA==10&&c.SwitchgearSelection.Rating.RatedA==40,"additional switch preserves primary protection values");Check(Engineering.Analyze(p).Checks.Any(x=>x.Rule=="Fusível / seccionador nominal"&&x.Status=="Atende comparações nominais"),"selected device appears in study");r.Source="Edited afterwards";Check(c.SwitchgearSelection.Rating.Source.Contains("Ensaio"),"binding owns independent source snapshot");c.Protection.MagneticTripA=250;Check(SwitchgearSelection.Evaluate(p,Engineering.Analyze(p),c,c.SwitchgearSelection).Status=="Dados incompletos","changed primary settings invalidate protecting association");c.Protection.MagneticTripA=0;Check(SwitchgearSelection.Evaluate(p,Engineering.Analyze(p),c,c.SwitchgearSelection).Status=="Atende comparações nominais","restored exact protecting settings");var old=c.SwitchgearSelection;var bad=Switch();bad.IcwKA=5;Reject(delegate{SwitchgearSelection.Apply(p,c,bad,bad.Family,PoleLayout.ThreePole,true);},"bad application rejected");Check(Object.ReferenceEquals(old,c.SwitchgearSelection),"failed application preserves original selection");
string csv=Path.Combine(dir,"table.csv");SwitchgearSelection.Export(new[]{Fuse(),Switch()},csv);var imported=SwitchgearSelection.Import(csv);Check(imported.Count==2&&imported[0].Source==Fuse().Source,"CSV quotes Unicode and mixed families roundtrip");SwitchgearSelection.Export(new SwitchgearRating[0],Path.Combine(dir,"empty.csv"));Check(SwitchgearSelection.Import(Path.Combine(dir,"empty.csv")).Count==0,"empty template imports");SwitchgearSelection.Export(imported,csv);var before=File.ReadAllBytes(csv);var backup=File.ReadAllBytes(csv+".bak");bad=Fuse();bad.Source="";Reject(delegate{SwitchgearSelection.Export(new[]{bad},csv);},"missing source rejected");Check(File.ReadAllBytes(csv).SequenceEqual(before)&&File.ReadAllBytes(csv+".bak").SequenceEqual(backup),"invalid export preserves destination and backup");Reject(delegate{SwitchgearSelection.Export(new[]{Fuse(),Fuse()},csv);},"duplicate condition rejected");bad=Switch();bad.BreakingKA=10;Reject(bad.Validate,"switch cannot claim short circuit interruption");bad=Fuse();bad.IcwKA=10;Reject(bad.Validate,"fuse cannot silently use switch withstand fields");bad=Switch();bad.IcwSeconds=0;Reject(bad.Validate,"withstand requires rated duration");foreach(double x in new[]{-1,double.NaN,double.PositiveInfinity}){bad=Switch();bad.IcmPeakKA=x;Reject(bad.Validate,"invalid making capacity rejected");}bad=Fuse();bad.Family=(SwitchgearFamily)99;Reject(bad.Validate,"unknown family rejected");string large=Path.Combine(dir,"large.csv");using(var stream=File.Create(large))stream.SetLength(32L*1024*1024+1);Reject(delegate{SwitchgearSelection.Import(large);},"oversized import rejected");var huge=new List<SwitchgearRating>();string big=new string('x',2000);for(int i=0;i<6000;i++){var x=Switch();x.Reference="BIG"+i;x.Source=x.DataVersion=x.Sheet=big;huge.Add(x);}Reject(delegate{SwitchgearSelection.Export(huge,csv);},"oversized export rejected");Check(File.ReadAllBytes(csv).SequenceEqual(before)&&File.ReadAllBytes(csv+".bak").SequenceEqual(backup)&&Directory.GetFiles(dir,"*.tmp").Length==0,"size overflow preserves library backup and cleans temp");
string project=Path.Combine(dir,"project.circuito");p.Save(project);string saved=File.ReadAllText(project);Check(saved.Contains("switchgear-selection-v1")&&saved.Contains("\"FileVersion\":4"),"selection uses guarded capability");var loaded=Project.Load(project);Check(loaded.Boards[0].Circuits[0].SwitchgearSelection.Rating.Reference=="SW40","selection survives reopen");Check(EngineeringReport.Memory(p,Engineering.Analyze(p))==EngineeringReport.Memory(loaded,Engineering.Analyze(loaded)),"report with additional device reproduces after reopen");var copy=ProjectEditing.DuplicateCircuit(p,p.Boards[0],c);Check(copy.SwitchgearSelection!=c.SwitchgearSelection&&copy.SwitchgearSelection.Rating!=c.SwitchgearSelection.Rating,"duplication owns independent device and source");p.Boards[0].Circuits.Remove(copy);File.WriteAllText(project,saved.Replace(SwitchgearSelection.EngineId,"future-switchgear-engine"));Reject(delegate{Project.Load(project);},"unknown device evaluator revision rejected");File.WriteAllText(project,saved);string previous=Environment.GetEnvironmentVariable("CIRCUITO_QA_PREVIOUS_EXE");if(!String.IsNullOrWhiteSpace(previous)){var assembly=Assembly.LoadFile(Path.GetFullPath(previous));bool rejected=false;try{assembly.GetType("CircuitoStudio.Project").GetMethod("Load").Invoke(null,new object[]{project});}catch(TargetInvocationException ex){rejected=ex.InnerException is InvalidDataException;}Check(rejected,"actual prior executable rejects new device capability");}
string artifacts=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-fusiveis");Directory.CreateDirectory(artifacts);p.Save(Path.Combine(artifacts,"origem.circuito"));SwitchgearSelection.Export(imported,Path.Combine(artifacts,"tabela.csv"));EngineeringReport.Materials(p,Path.Combine(artifacts,"materiais.csv"));Check(File.ReadAllText(Path.Combine(artifacts,"materiais.csv")).Contains("SW40")&&File.ReadAllText(Path.Combine(artifacts,"materiais.csv")).Contains("Seccionador selecionado"),"materials include additional selected assembly");File.WriteAllText(Path.Combine(artifacts,"resultado.txt"),SwitchgearSelection.Evaluate(p,Engineering.Analyze(p),c,c.SwitchgearSelection).Detail,new UTF8Encoding(true));using(var form=new SwitchgearSelectionForm(p,c,csv)){form.CreateControl();Check(!form.Changed,"opening selector does not change project");if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(10,10);form.Show();Application.DoEvents();using(var bitmap=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var graphics=Graphics.FromImage(bitmap))graphics.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bitmap.Save(Path.Combine(artifacts,"fusiveis.png"));}form.Hide();}}
Console.WriteLine("PASS: "+n+" fuse/switchgear assertions");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{Directory.Delete(dir,true);}}
}
